Literal.Value:
'{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "description": "Page footer: a line-coloured rule along the top, the report and page on the left and the page''s source systems with their last refresh on the right, both in muted mono.",
  "data": {
    "name": "dataset"
  },
  "width": "container",
  "height": "container",
  "background": "transparent",
  "padding": 0,
  "params": [
    {
      "name": "muted",
      "expr": "pbiColor(6)"
    },
    {
      "name": "line",
      "expr": "pbiColor(8)"
    }
  ],
  "transform": [
    {
      "filter": "isValid(datum[''Page Footer Left'']) || isValid(datum[''Page Sources Refreshed''])"
    },
    {
      "calculate": "isValid(datum[''Page Footer Left'']) ? datum[''Page Footer Left''] + '''' : ''''",
      "as": "leftText"
    },
    {
      "calculate": "isValid(datum[''Page Sources Refreshed'']) ? datum[''Page Sources Refreshed''] + '''' : ''''",
      "as": "sourcesText"
    }
  ],
  "layer": [
    {
      "mark": {
        "type": "rule",
        "x": 0,
        "x2": {
          "expr": "width"
        },
        "y": 0.5,
        "strokeWidth": 1,
        "color": {
          "expr": "line"
        }
      },
      "encoding": {
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "left",
        "baseline": "middle",
        "x": 0,
        "y": {
          "expr": "height / 2 + 2"
        },
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "color": {
          "expr": "muted"
        },
        "limit": {
          "expr": "width * 0.3"
        }
      },
      "encoding": {
        "text": {
          "field": "leftText"
        },
        "tooltip": null
      }
    },
    {
      "mark": {
        "type": "text",
        "align": "right",
        "baseline": "middle",
        "x": {
          "expr": "width"
        },
        "y": {
          "expr": "height / 2 + 2"
        },
        "font": "JetBrains Mono, Consolas, monospace",
        "fontSize": 12.5,
        "color": {
          "expr": "muted"
        },
        "limit": {
          "expr": "width * 0.68"
        }
      },
      "encoding": {
        "text": {
          "field": "sourcesText"
        },
        "tooltip": [
          {
            "field": "sourcesText",
            "title": "Sources"
          }
        ]
      }
    }
  ]
}'

'{
  "background": "transparent",
  "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
  "padding": 8,
  "view": {
    "stroke": null
  },
  "title": {
    "font": "Fraunces, Cambria, Georgia, serif",
    "fontSize": 17,
    "fontWeight": 600,
    "color": "#0F4D43",
    "anchor": "start",
    "offset": 12
  },
  "axis": {
    "domain": false,
    "ticks": false,
    "grid": true,
    "gridColor": "#E6E8E2",
    "gridWidth": 1,
    "labelColor": "#5F6E69",
    "labelFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "labelFontSize": 12,
    "labelPadding": 8,
    "titleColor": "#5F6E69",
    "titleFont": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "titleFontSize": 12,
    "titleFontWeight": "normal"
  },
  "axisX": {
    "grid": false
  },
  "legend": {
    "disable": true
  },
  "range": {
    "category": [
      "#0F4D43",
      "#0B8A6B",
      "#5E8C82",
      "#B9852C",
      "#B6462F",
      "#2A6A5F",
      "#5F6E69",
      "#CFDDD4",
      "#D6D9D2"
    ]
  },
  "text": {
    "font": "Segoe UI, wf_segoe-ui_normal, Arial, sans-serif",
    "color": "#0F4D43"
  },
  "line": {
    "color": "#0F4D43",
    "strokeWidth": 2.5,
    "strokeJoin": "round",
    "strokeCap": "round"
  },
  "point": {
    "color": "#0B8A6B",
    "filled": true
  },
  "rule": {
    "color": "#D6D9D2"
  }
}'
